"""Lệnh CLI `rfcv` (adapter, rbs, verify, plugins, run)."""from __future__ import annotationsfrom pathlib import Pathfrom typer.testing import CliRunnerfrom conftest import ADAPTER_DIRfrom rfcv.ui.cli import appdef test_cli_commands(tmp_path: Path) -> None:    runner = CliRunner()    assert runner.invoke(app, ["adapter", "check", str(ADAPTER_DIR)]).exit_code == 0    r = runner.invoke(        app, ["rbs", "check", str(ADAPTER_DIR / "examples" / "TLS13-0042.rbs"), "--adapter", str(ADAPTER_DIR)]    )    assert r.exit_code == 0 and "at_limit:record.length=16640" in r.output    assert runner.invoke(app, ["verify", str(tmp_path)]).exit_code == 0    plugins = runner.invoke(app, ["plugins"])    assert plugins.exit_code == 0 and "rfc_protocol" in plugins.output and "scenario_result" in plugins.output    # chưa có chỉ mục mã, bộ chạy lệnh và bộ chạy SUT thật: `run` phải nói rõ thiếu gì, không chạy dở    run = runner.invoke(        app,        [            "run",            "--adapter",            str(ADAPTER_DIR),            "--run-dir",            str(tmp_path / "runs"),            "--skills",            str(ADAPTER_DIR.parent.parent / "skills"),        ],    )    assert run.exit_code == 2 and "code_index" in run.output and "sut_launcher" in run.output